{
  "name": "freshrss-hello-world",
  "type": "module",
  "description": "Extension example for FreshRSS",
  "homepage": "https://github.com/FreshRSS/xExtension-HelloWorld",
  "readmeFilename": "README.md",
  "bugs": {
    "url": "https://github.com/FreshRSS/xExtension-HelloWorld/issues"
  },
  "keywords": [
    "freshrss",
    "extensions"
  ],
  "repository": {
    "type": "git",
    "url": "https://github.com/FreshRSS/xExtension-HelloWorld.git"
  },
  "license": "AGPL-3.0",
  "engines": {
    "node": ">=18"
  },
  "scripts": {
    "eslint": "eslint .",
    "eslint_fix": "eslint --fix .",
    "test": "npm run eslint",
    "fix": "npm run eslint_fix"
  },
  "devDependencies": {
    "eslint": "^9.39.1",
    "@eslint/js": "^9.39.1",
    "globals": "^16.5.0",
    "neostandard": "^0.12.2"
  }
}

{
	"default": true,
	"blanks-around-fences": false,
	"blanks-around-lists": false,
	"first-line-heading": false,
	"line-length": false,
	"no-hard-tabs": false,
	"no-inline-html": {
		"allowed_elements": ["br", "img", "kbd", "details", "summary"]
	},
	"no-multiple-blanks": {
		"maximum": 2
	},
	"no-trailing-spaces": true,
	"ul-indent": false,
	"ul-style": {
		"style": "consistent"
	}
}

import globals from "globals";
import js from "@eslint/js";
import neostandard, { resolveIgnoresFromGitignore } from 'neostandard';
import stylistic from '@stylistic/eslint-plugin';

export default [
	{
		files: ["**/*.js"],
		languageOptions: {
			globals: {
				...globals.browser,
			},
			sourceType: "script",
		},
	},
	{
		ignores: [
			...resolveIgnoresFromGitignore(),
			"**/*.min.js",
		],
	},
	js.configs.recommended,
	// stylistic.configs['recommended-flat'],
	...neostandard(),
	{
		plugins: {
			"@stylistic": stylistic,
		},
		rules: {
			"camelcase": "off",
			"eqeqeq": "off",
			"no-empty": ["error", { "allowEmptyCatch": true }],
			"no-unused-vars": ["error", {
				"args": "none",
				"caughtErrors": "none",
			}],
			"object-shorthand": "off",
			"yoda": "off",
			"@stylistic/indent": ["warn", "tab", { "SwitchCase": 1 }],
			"@stylistic/linebreak-style": ["error", "unix"],
			"@stylistic/max-len": ["warn", 165],
			"@stylistic/no-tabs": "off",
			"@stylistic/quotes": ["off", "single", { "avoidEscape": true }],
			"@stylistic/quote-props": ["warn", "consistent"],
			"@stylistic/semi": ["warn", "always"],
			"@stylistic/space-before-function-paren": ["warn", {
				"anonymous": "always",
				"asyncArrow": "always",
				"named": "never",
			}],
		},
	},
];
